#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#include<math.h>
#define D 768
#define H 12
#define L 12
#define V 50257
#define N 1024
#define F 3072
#define R 64
float*C,*W[L][12],*lb,*lg,*we,*pe,*x,*kc[L],*vc[L];
int IL=0;
void ln(float*o,float*x,float*g,float*b){float m=0,v=0;
 for(int j=0;j<D;j++)m+=x[j];m/=D;
 for(int j=0;j<D;j++){float d=x[j]-m;v+=d*d;}
 v=sqrtf(v/D+1e-5f);for(int j=0;j<D;j++)o[j]=(x[j]-m)/v*g[j]+b[j];}
void mm(float*o,float*x,float*w,float*b,int d,int k){
 for(int j=0;j<d;j++){float s=b?b[j]:0;for(int p=0;p<k;p++)s+=x[p]*w[p*d+j];o[j]=s;}}
float nrm(float*x,int n){float s=0;for(int i=0;i<n;i++)s+=x[i]*x[i];return sqrtf(s);}
void fwd(int p){float xn[D],q[3*D],a[D],pr[D],x2[D],h[F],h2[D],sc[N];
 for(int l=0;l<L;l++){
  ln(xn,x+p*D,W[l][5],W[l][4]);mm(q,xn,W[l][1],W[l][0],3*D,D);
  memcpy(kc[l]+p*D,q+D,D*4);memcpy(vc[l]+p*D,q+2*D,D*4);
  for(int hh=0;hh<H;hh++){float mx=-1e9f;
   for(int j=0;j<=p;j++){float s=0;
    for(int d=0;d<R;d++){int qi=IL?d*H+hh:hh*R+d;int ki=IL?j*D+d*H+hh:j*D+hh*R+d;s+=q[qi]*kc[l][ki];}
    s*=.125f;sc[j]=s;if(s>mx)mx=s;}
   float sm=0;for(int j=0;j<=p;j++){sc[j]=expf(sc[j]-mx);sm+=sc[j];}
   for(int d=0;d<R;d++){float s=0;for(int j=0;j<=p;j++){int vi=IL?j*D+d*H+hh:j*D+hh*R+d;s+=sc[j]/sm*vc[l][vi];}int ai=IL?d*H+hh:hh*R+d;a[ai]=s;}}
  mm(pr,a,W[l][3],W[l][2],D,D);for(int j=0;j<D;j++)x[p*D+j]+=pr[j];
  if(p<4&&l<4)printf("p%d L%d after attn: |x|=%.2f\n",p,l,nrm(x+p*D,D));
  ln(x2,x+p*D,W[l][7],W[l][6]);mm(h,x2,W[l][9],W[l][8],F,D);
  for(int j=0;j<F;j++){float t=h[j];h[j]=.5f*t*(1.f+tanhf(.7978845608f*(t+.044715f*t*t*t)));}
  mm(h2,h,W[l][11],W[l][10],D,F);for(int j=0;j<D;j++)x[p*D+j]+=h2[j];
  if(p<4&&l<4)printf("p%d L%d after mlp:  |x|=%.2f\n",p,l,nrm(x+p*D,D));
 }}
int main(){C=malloc(497759232);FILE*f=fopen("/app/gpt2-124M.ckpt","rb");fread(C,4,124439808,f);fclose(f);
 float*p=C;
 for(int l=0;l<L;l++){W[l][0]=p;p+=3*D;W[l][1]=p;p+=3*D*D;W[l][2]=p;p+=D;
  W[l][3]=p;p+=D*D;W[l][4]=p;p+=D;W[l][5]=p;p+=D;W[l][6]=p;p+=D;
  W[l][7]=p;p+=D;W[l][8]=p;p+=F;W[l][9]=p;p+=F*D;W[l][10]=p;p+=D;W[l][11]=p;p+=F*D;}
 lb=p;p+=D;lg=p;p+=D;pe=p;p+=N*D;we=p;p+=V*D;
 for(int il=0;il<2;il++){IL=il;
  x=calloc(N*D,4);for(int l=0;l<L;l++){kc[l]=calloc(N*D,4);vc[l]=calloc(N*D,4);}
  int toks[]={7454,2402,257,640};
  for(int i=0;i<4;i++)for(int j=0;j<D;j++)x[i*D+j]=we[toks[i]*D+j]+pe[i*D+j];
  printf("\n=== IL=%d ===\n",il);
  for(int i=0;i<4;i++){printf("emb p%d: |x|=%.2f\n",i,nrm(x+i*D,D));fwd(i);}
  float xn[D];ln(xn,x+3*D,lg,lb);
  float scores[V];for(int j=0;j<V;j++){float s=0;for(int d=0;d<D;d++)s+=xn[d]*we[j*D+d];scores[j]=s;}
  printf("IL=%d pred:",il);
  for(int t=0;t<5;t++){int best=0;float mx=-1e9f;for(int j=0;j<V;j++)if(scores[j]>mx){mx=scores[j];best=j;}printf(" %d(%.1f)",best,mx);scores[best]=-1e9f;}
  printf("\n");
  free(x);for(int l=0;l<L;l++){free(kc[l]);free(vc[l]);}
 }
 return 0;}
